/* =====================================================================
   FTA · brand swap (12 Nov 2026, premium refresh)
   Three jobs:
   1 · Swap every <img data-logo="…"> src with the new gold FTA mark
       (no dark square background anywhere — just the mark floating).
   2 · Swap the printed documents' logo (receipts, slips, vouchers) too.
   3 · After the dashboard first renders, stagger-fade its KPI cards and
       count up the big figures — matches the dashboard motion the owner
       approved (v28).
   Nothing here changes data, business rules, or page routing.
   ===================================================================== */
(function () {
  'use strict';

  /* new logo (full) — ACADEMY + mark + wordmark, as the owner approved */
  const SVG_FULL = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="65 60 1333 953"><defs><linearGradient id="ftaG" x1="0" y1="0" x2="0.35" y2="1"><stop offset="0" stop-color="#7A4A12"/><stop offset="0.22" stop-color="#B07A28"/><stop offset="0.45" stop-color="#F6D98A"/><stop offset="0.58" stop-color="#E2B451"/><stop offset="0.8" stop-color="#A86F1E"/><stop offset="1" stop-color="#6E420F"/></linearGradient></defs><g fill="url(#ftaG)">__SVGBODY__</g></svg>';
  /* new logo (mark only) — for tight spaces (sidebar brand tile) */
  const SVG_MARK = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="280 40 870 870"><defs><linearGradient id="ftaGM" x1="0" y1="0" x2="0.35" y2="1"><stop offset="0" stop-color="#7A4A12"/><stop offset="0.22" stop-color="#B07A28"/><stop offset="0.45" stop-color="#F6D98A"/><stop offset="0.58" stop-color="#E2B451"/><stop offset="0.8" stop-color="#A86F1E"/><stop offset="1" stop-color="#6E420F"/></linearGradient></defs><g fill="url(#ftaGM)">__SVGBODY_MARK__</g></svg>';

  /* dynamically loaded from /brand/fta-full.svg + /brand/fta-mark.svg so this file stays small.
     Falls back to the old PNGs when the new SVGs are not on the server. */
  const LOAD = url => fetch(url, { cache: 'force-cache' }).then(r => r.ok ? r.text() : '').catch(() => '');

  /* the new gold mark + wordmark, inlined so the swap works everywhere, even offline */
  const FULL_DATA = 'data:image/svg+xml;base64,';
  const MARK_DATA = 'data:image/svg+xml;base64,';
  const READY = true;
  let pending = false;
  new MutationObserver(() => { if (pending) return; pending = true; requestAnimationFrame(() => { pending = false; swap(); }); }).observe(document.body, { childList: true, subtree: true });
  /* also swap when the sidebar opens/collapses or the viewport crosses the breakpoint */
  const reSwap = () => { pending = false; swap(); };
  const side = () => document.getElementById('side');
  const hookSide = () => { const s = side(); if (!s) return; s.addEventListener('mouseenter', reSwap); s.addEventListener('mouseleave', reSwap); };
  setTimeout(hookSide, 300);
  window.addEventListener('resize', reSwap);
  document.addEventListener('transitionend', e => { if (e.target && e.target.id === 'side') reSwap(); });
  swap();

  function swap() {
    if (!READY || !FULL_DATA) return;
    document.querySelectorAll('img[data-logo]').forEach(img => {
      const kind = img.getAttribute('data-logo');
      /* in tight spots (sidebar brand next to the academy name, top-bar) the mark alone is cleaner;
         everywhere else — login screen, splash, receipts — the full wordmark */
      /* only the sidebar brand tile uses the compact mark (text sits next to it);
         the top-bar logo wants the full wordmark, as the owner asked on the artifact comment */
      /* the sidebar brand uses the full logo too (with wordmark + subtitle),
         as the owner asked; a desktop collapsed rail still needs the compact
         mark (otherwise it overflows). Everywhere else (top-bar, splash,
         receipts, login) wants the full wordmark. */
      const sideBrand = img.closest('#side .brand');
      const collapsedRail = sideBrand && !document.body.classList.contains('side-pin') && !document.body.classList.contains('fta-drawer') && !matchMedia('(max-width:899px)').matches && !sideBrand.closest('#side:hover');
      const tinyMark = img.closest('.fta-nav-mini');
      const want = tinyMark ? (MARK_DATA || FULL_DATA) : (collapsedRail ? (MARK_DATA || FULL_DATA) : ((kind === 'em' || kind === 'mark' || kind === 's') ? (MARK_DATA || FULL_DATA) : FULL_DATA));
      if (img.src !== want) img.src = want;
      /* no dark square behind the logo anywhere — matches the QIT-style preview the owner approved */
      const box = img.parentElement;
      if (box && !box.hasAttribute('data-fta-no-bg')) {
        box.style.background = 'transparent';
        box.style.boxShadow = 'none';
        box.setAttribute('data-fta-no-bg', '1');
      }
    });
    /* splash screen (fta-boot) */
    const splash = document.querySelector('#fta-boot img, #fta-boot svg');
    if (splash && splash.tagName === 'IMG' && splash.src !== FULL_DATA) splash.src = FULL_DATA;
  }

  /* ----- dashboard motion ---------------------------------------------- */
  const KPI_SEL = '#view .kpis .kpi, #view .cc-k .cck, #view .qc .qc-b > *';
  let motionRun = false;
  function playMotion() {
    const host = document.querySelector('#view');
    if (!host || host.getAttribute('data-page') !== 'dashboard') { motionRun = false; return; }
    if (motionRun) return;
    const tiles = host.querySelectorAll(KPI_SEL);
    if (!tiles.length) return;
    motionRun = true;
    tiles.forEach((el, i) => {
      el.style.animation = 'ftaKpiIn 480ms cubic-bezier(.2,.9,.2,1) both';
      el.style.animationDelay = (i * 55) + 'ms';
    });
    /* no count-up — the CSS stagger-in motion is enough; count-up caused a brief mid-number wrap on narrow screens */
  }
  /* re-run on every page change (the app replaces #view each time) */
  const mo = new MutationObserver(() => { const host = document.querySelector('#view'); if (host && host.getAttribute('data-page') === 'dashboard' && !motionRun) requestAnimationFrame(playMotion); });
  mo.observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['data-page'] });
  /* also when the dashboard first comes into view (first paint timing) */
  setTimeout(() => { motionRun = false; playMotion(); }, 450);
  /* if the page key changes, reset the counter so the motion plays again */
  let lastPage = '';
  setInterval(() => { try { const p = document.querySelector('#view')?.getAttribute('data-page') || ''; if (p !== lastPage) { lastPage = p; motionRun = false; if (p === 'dashboard') requestAnimationFrame(playMotion); } } catch (e) { } }, 500);



  /* ----- mobile side-drawer (QIT style) --------------------------------- */
  const SVG_HAMB = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><path d="M4 7h16M4 12h16M4 17h10"/></svg>';
  function closeDrawer() { document.body.classList.remove('fta-drawer'); }
  function openDrawer()  { document.body.classList.add('fta-drawer'); }
  function toggleDrawer() { document.body.classList.toggle('fta-drawer'); }

  function installDrawer() {
    const topL = document.querySelector('#top .top-r') || document.querySelector('#top .top-l') || document.querySelector('#top');
    const existing = document.getElementById('fta-hamb');
    if (existing && existing.parentElement !== topL) existing.remove();   /* re-inject into the new parent */
    if (topL && !document.getElementById('fta-hamb') && window.matchMedia('(max-width: 899px)').matches) {
      const btn = document.createElement('button');
      btn.id = 'fta-hamb'; btn.type = 'button'; btn.setAttribute('aria-label', 'Menu'); btn.innerHTML = SVG_HAMB;
      btn.addEventListener('click', toggleDrawer);
      topL.insertBefore(btn, topL.firstChild);
    }
    const side = document.getElementById('side');
    if (side && !document.getElementById('fta-drawer-x') && window.matchMedia('(max-width: 899px)').matches) {
      const x = document.createElement('button');
      x.id = 'fta-drawer-x'; x.type = 'button'; x.setAttribute('aria-label', 'Close menu'); x.textContent = '×';
      x.addEventListener('click', closeDrawer);
      side.appendChild(x);
    }
  }
  installDrawer();
  /* re-install after any page re-render */
  new MutationObserver(() => { if (!document.getElementById('fta-hamb') || !document.getElementById('fta-drawer-x')) installDrawer(); }).observe(document.body, { childList: true, subtree: true });
  /* backdrop click closes */
  document.addEventListener('click', e => {
    if (!document.body.classList.contains('fta-drawer')) return;
    if (e.target === document.body || e.target === document.documentElement) closeDrawer();
  }, true);
  document.body.addEventListener('click', e => {
    if (!document.body.classList.contains('fta-drawer')) return;
    const side = document.getElementById('side'); if (!side) return;
    const clickedInsideSide = side.contains(e.target);
    const clickedHamb = e.target.closest('#fta-hamb');
    if (!clickedInsideSide && !clickedHamb) closeDrawer();
  }, false);
  /* Escape closes */
  document.addEventListener('keydown', e => { if (e.key === 'Escape' && document.body.classList.contains('fta-drawer')) closeDrawer(); });
  /* tapping a nav item in the drawer closes it */
  document.addEventListener('click', e => {
    if (!document.body.classList.contains('fta-drawer')) return;
    const link = e.target.closest('#side #sidenav a, #side #sidenav button, #side .brand a');
    if (link) setTimeout(closeDrawer, 80);
  }, true);
  /* also close on resize past breakpoint */
  window.addEventListener('resize', () => { if (window.innerWidth >= 900) closeDrawer(); });

  /* ----- click ripple on every sidebar nav button ---------------------- */
  document.addEventListener('pointerdown', e => {
    const b = e.target.closest('#side .nav');
    if (!b) return;
    const r = b.getBoundingClientRect();
    b.style.setProperty('--rx', (e.clientX - r.left) + 'px');
    b.style.setProperty('--ry', (e.clientY - r.top) + 'px');
    b.classList.remove('fta-rip');
    /* force reflow so the animation restarts even on rapid taps */
    void b.offsetWidth;
    b.classList.add('fta-rip');
    setTimeout(() => b.classList.remove('fta-rip'), 600);
  }, true);
  window.FTA_BRAND = Object.assign(window.FTA_BRAND || {}, { swap, playMotion, openDrawer, closeDrawer, toggleDrawer });
})();
